b7.content:
{
  "elements": [
    {
      "id": "corrowby",
      "primitive": "node_card",
      "props": {
        "title": "CORROWBY",
        "subtitle": "counts tokens",
        "icon": "server",
        "semantic": "neutral"
      },
      "zone": "around"
    },
    {
      "id": "model-card",
      "primitive": "node_card",
      "props": {
        "title": "MODEL",
        "subtitle": "its own tokenizer",
        "icon": "brain",
        "semantic": "focus"
      },
      "zone": "center"
    },
    {
      "id": "link",
      "primitive": "connector",
      "props": {
        "from": "corrowby",
        "to": "model-card",
        "label": "calls",
        "semantic": "concept"
      }
    },
    {
      "id": "tag-exact",
      "primitive": "tag",
      "props": {
        "text": "exact tokenizer",
        "semantic": "focus",
        "pin": {
          "to": "model-card",
          "side": "bottom"
        }
      }
    },
    {
      "id": "tag-budget",
      "primitive": "tag",
      "props": {
        "text": "budgets in tokens",
        "semantic": "concept",
        "pin": {
          "to": "corrowby",
          "side": "bottom"
        }
      }
    }
  ],
  "events": [
    {
      "at": { "type": "word", "index": 1 },
      "action": "enter",
      "targets": ["corrowby"]
    },
    {
      "at": { "type": "word", "index": 3 },
      "action": "enter",
      "targets": ["tag-budget"]
    },
    {
      "at": { "type": "word", "index": 6 },
      "action": "enter",
      "targets": ["model-card"]
    },
    {
      "at": { "type": "word", "index": 7 },
      "action": "enter",
      "targets": ["tag-exact"]
    },
    {
      "at": { "type": "word", "index": 10 },
      "action": "enter",
      "targets": ["link"]
    }
  ],
  "focus": ["model-card"],
  "transitionIn": "fade"
}
